    y_count = {}

    # Count occurrences of each x and y coordinate
    for x, y in points:
        if x in x_count:
            x_count[x] += 1
        else:
            x_count[x] = 1

        if y in y_count:
            y_count[y] += 1
        else:
            y_count[y] = 1

    # Calculate the number of right triangles
    triangles = 0
