def count_right_triangles(N, points):
    x_count = {}
    y_count = {}
    result = 0

    for x, y in points:
        if x in x_count:
            result += x_count[x] * (y_count[y] - 1)
        if y in y_count:
            result += y_count[y] * (x_count[x] - 1)
        x_count[x] = x_count.get(x, 0) + 1
        y_count[y] = y_count.get(y, 0) + 1

    return result

