def count_right_triangles(N, points):
    x_count = {}
    y_count = {}

    for x, y in points:
        if x not in x_count:
            x_count[x] = 0
        x_count[x] += 1

        if y not in y_count:
            y_count[y] = 0
        y_count[y] += 1

    total_triangles = 0

    for x, y in points:
        total_triangles += (x_count[x] - 1) * (y_count[y] - 1)

    return total_triangles

